$(".object").glueLive("glue-object-lock",function(a){if($(this).hasClass("locked")){var m=$.glue.object.moveable_of(this);if(m){m.draggable=false;m.resizable=false}if($(this).hasClass("text")){$(this).children("textarea").css("resize","none")}}});$(document).ready(function(){$(".object").glueTrigger("glue-object-lock");var a;$.glue.contextmenu.hide();a=$('<img src="'+$.glue.base_url+'modules/lock/lock.png" alt="btn" title="lock object" width="32" height="32">');$(a).bind("glue-menu-activate",function(d){var c=$.glue.owner(this);var b;if($(c).hasClass("locked")){b="object is locked, click to unlock it"}else{b="lock object"}$(this).attr("title",b)});$(a).bind("click",function(d){var b=this;var c=$.glue.owner(this);var m=$.glue.object.moveable_of(c);if($(c).hasClass("locked")){$(c).removeClass("locked");if(m){m.draggable=true;m.resizable=$(c).hasClass("resizable")&&$(c).hasClass("glue-selected")}$.glue.contextmenu.hide();$.glue.contextmenu.show(c)}else{$(c).addClass("locked");if(m){m.draggable=false;m.resizable=false}if($(c).hasClass("text")){$(c).children("textarea").css("resize","none")}$.glue.contextmenu.hide();$.glue.contextmenu.show(c)}$(b).glueTrigger("glue-menu-activate");$.glue.object.save(c)});$.glue.contextmenu.register("object","object-lock",a,19)});